"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3202],{46348:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"SkillTreeService","desc":"Permanent skill upgrade tree \u2014 a persistent coin sink. Lobby only:\\nplayers buy `SkillTreeData` nodes with coins; owned nodes save to\\n`profile.skillNodes` and replicate to the client through the normal\\nprofile replica (the tree UI reads `ClientState.playerData.skillNodes`).\\n\\nPrerequisites are validated server-side (`SkillTreeData.canBuy`) \u2014 a\\nclient asking for a node whose parents aren\'t owned is rejected before\\nany coins move. Effects are applied by the game\'s own systems, which\\nread owned nodes via `getOwned` (or levels via\\n`SkillTreeData.statLevels`).\\n\\nGated behind `FeatureFlags.SkillTree`: with it off, `init` binds no\\nhandlers, so `BUY_SKILL_NODE` gets no reply.","source":{"line":21,"path":"src/Server/Features/SkillTree/SkillTreeService.luau"}}')}}]);